  AwakerTalent_122607_TalentDesc_1 = {
    Text = "Nachdem sie 2 „Schlag“-Karten gespielt hat, führt Mouchette einen Folgeangriff aus, der zufällig Schaden in Höhe von 30% von Mouchettes Angriff verursacht, was als „Schlag“ gilt. Dies kann pro Runde maximal 4 Mal wirksam werden."
  },
  AwakerTalent_122607_TalentName_1 = {
    Text = "Dramatische Begegnung"
  },
  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Dieses Talent ist nur in den „Astrales Reich“-Stufen wirksam.\nKON, ANG und VERT dieses Erweckers +[Arg1]%, und er erhält [Arg2] Keyflare beim ersten Erwecken.\nGift-Auslöse-Effekt aller Erwecker +[Arg3]%. \nJeder Stapel „Betrunkenheit“ reduziert zusätzlich den von „Humanoiden“ Feinden verursachten Schaden um 1%, und wenn „Betrunkenheit“ entfernt wird, verursacht jeder Stapel einen Festgesetzten Schaden in Höhe von 1% der Max LP des Ziels bei „Humanoiden“ Feinden."
  },
  AwakerTalent_125362_TalentDesc_10 = {
