  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Wenn Arachne im Team ist, wird das Ultra-Reich zu Singularität: Ultra umgewoben.\nDimensionsgleiter: Nach dem Spielen der ersten Befehlskarte jeder Runde wird eine flüchtige Basiskopie davon in den Hyperraum gelegt und erhält 25 Stapelungen Singularitätslaterne. Dies kann während Ultra-Runden nicht ausgelöst werden. Wenn eine Karte den Dimensionsgleiter auslöst, profitiert sie auch von den Effekten der Singularitätslaterne.\nSingularitätslaterne: Pro Stapelung erhöhen sich Gesamtschaden, Feste Stärke & Tentakelschaden-Gewinn, Festes Gift & Gegenangriff einer Karte jeweils um +2 %; Finaler Schild, LP-Wiederherstellung und STR▼ jeweils um +1 %. Dieser Effekt wird gelöscht, wenn die Karte gespielt wird. Karten mit diesem Effekt können den Dimensionsgleiter nicht auslösen.\nHyperrraum: Wenn er voll ist, beendet der Beginn der Ultra-Runde die Runde nicht und beginnt auch keine neue; alle Nicht-Behalten-Karten werden abgeworfen, ihre Nichtigkeitseffekte werden aufgelöst, alle Karten aus dem Hyperraum werden gezogen und die Arithmetica wird auf 5 gesetzt. Die aktuelle Runde wird als Ultra-Runde fortgesetzt.\nSingularitätsvernichtung: Zieht die am weitesten links liegende Karte aus dem Hyperraum auf die Hand. 3 Runden Abklingzeit.\nZu Beginn der Untersuchung werden +50 % Schadenamplifikation und 15 Stapelungen Singularitätsprisma gewonnen.\nSingularitätsprisma: Die Effekte aller Befehlskarten werden so erhöht, als hätten sie diese Anzahl an Stapelungen Singularitätslaterne.\nÜberdimensionale Meisterschaft: Pro 1 Punkt Reichsbeherrschung erhöhen sich die Singularitätslaterne-Stapelungen aus Singularitätsprisma und Dimensionsgleiter um 0,05 %.\nReinste Hyperdimension: Wenn das Team nur aus Ultra- oder Chaoswachkörpern besteht, werden der Effekt der Überdimensionalen Meisterschaft und die Reich-Schadenamplifikation verdoppelt."
  },
  AwakerTalent_127223_TalentName_1 = {
    Text = "Schicksalsleine"
  },
