  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Dieses Talent ist nur in den „Sternekapitel„-Level wirksam.\nDie KON, ANG und VERT dieses Erweckten Körpers +[Arg1]%, und er erhält [Arg2] Keyflare beim ersten Erwecken.\nDer vom „Lied von Shaye„ ausgewählte Erweckter Körper erhält [Arg3] Stapelungen „Ausbreitungsfiesta„, und die nächste Posse wird 2-mal wirksam.\nShaye fügt „Fleisch„-Feinden +[Arg4]% Korrosionsstapelungen zu."
  },
