  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in den „Sternkapitel“-Stufen wirksam.\n·KON, ANG und Verteidigung dieses Erweckers werden um [Arg1]% erhöht, und nachdem dieser Erwecker zum ersten Mal Erwecken spielt, erhält er [Arg2] Keyflare.\n·Der STR▼-Effekt von „Grenzloser Wüstenschatten“ und der erhaltene STR-Multiplikator werden um [Arg3]% erhöht. Jedes Mal, wenn er wirksam wird, erhält der nächste „Sündenbefleckte Schusslinie“ einen zusätzlichen STR-Bonus von [Arg4]%, bis zu einem Maximum von 1200%."
  },
  AwakerTalent_130400_TalentDesc_10 = {
