  AwakerTalent_131854_TalentDesc_1 = {
    Text = "Wenn Shaye im Team ist, mutiert das Fleisch-Reich zu Zuchtfleisch.\n\nEmbryofusion: Die pro Runde erhaltene Embryofusion steigt auf 50–100, skalierend mit verlorenen LP. Die Embryofusions-Obergrenze steigt von 100 auf 200. Beim Erreichen der Obergrenze wird 1 „Propagul-Embryo\" auf die Hand gelegt.\n\nPropagul-Embryo: Das Spielen dieser Karte gewährt keine Krit. Rate mehr. Verschlingen gewährt keinen Schild oder Temporäre STR mehr. Wenn jeder Erwecker zum ersten Mal pro Runde einen „Propagul-Embryo\" verbraucht, erhält er 40 Stapelungen „Ausbreitungsfiesta\": Jede Stapelung verstärkt die folgenden Endeffekte der nächsten Verherrlichung dieses Erweckers in dieser Runde um 1 %: Gesamtschaden, Fester Schild, Feste LP-Wiederherstellung, Feste STR/STR▼, Tentakel-Schaden-Bonus, Festes Gift und Fester Konter.\n\nBlutroter Ofen: Die automatische Ansammlung zu Rundenbeginn ändert sich auf 10 % der verlorenen LP, bis zu 50 % der Max LP. Wird am Ende des Kampfes nicht mehr angesammelt. 3 Runden Abklingzeit.\n\nScharlachrote Erosion: Nach dem Einsatz des Blutroten Ofens wird allen Feinden Verfall in Höhe von 1 % ihrer Max LP zugefügt. Je mehr Blutroter Ofen verbraucht wurde, desto stärker der Verfall-Effekt, bis zu +100 %. Gegen „Leere Hülle\"-Feinde wird der 5-fache Verfall-Effekt angewendet.\n\nZu Beginn der Erkundung: Max LP +10 %, Team-Schadenamplifikation +50 %, und alle Erwecker erhalten zu Rundenbeginn 20 Stapelungen „Ausbreitungsfiesta\". Besteht das Team ausschließlich aus Fleisch- oder Chaos-Erweckern, wird die durch diesen Effekt gewährte Schadenamplifikation verdoppelt.\nDie Reichsbeherrschung wird zur „Zuchtfleisch-Beherrschung\": Jeder Punkt Reichsbeherrschung erhöht die durch „Zuchtfleisch\" erhaltenen „Ausbreitungsfiesta\"-Stapelungen um 0,05 %.\n\nBesteht das Team ausschließlich aus Fleisch- oder Chaos-Erweckern, wird der „Zuchtfleisch-Beherrschungs\"-Effekt verdoppelt."
  },
  AwakerTalent_131854_TalentName_1 = {
    Text = "Zuchtfleisch"
  },
