  AwakerTalent_141303_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in Sternekapitel-Levels wirksam.\n·Die KON, der ANG und die VERT dieses Erweckten erhöhen sich um [Arg1]%, und nach dem ersten Ausspielen von Erwecken erhält dieser Erweckte zusätzlich [Arg2] Punkte Keyflare.\n·Der festgesetzte Schaden, den „Pontos„ an „Das Gefolge der Verzückung„ verursacht, erhöht sich um [Arg3]%.\n·„Unerbittliche Jagd„ erhält für je 10 verbrauchte Aliemus Tentakelschaden in Höhe von [Arg4]% ANG. Wenn „Gauntverheerung„ Schaden verursacht, wird die STR des Ziels vorübergehend um einen Betrag in Höhe von [Arg5]% VERT reduziert."
  },
