  AwakerTalent_143615_TalentDesc_1 = {
    Text = "Wenn sich dieser Charakter im Team befindet, verwandelt sich das Aequor-Reich in das „Benthos: Aequor„-Reich.\n\nDer Basis-Tentakelschaden wird auf 5% der Max LP des Teams geändert.\n\nTeam-Schadenamplifikation +50% nach Erkundungsbeginn (Effekt verdoppelt, wenn das Team ausschließlich aus Aequor- und Chaos-Reich-Erweckern besteht, jedoch werden keine zusätzlichen Start-Tentakel erhalten).\nDer Tentakelansammlungs-Effekt wird entfernt.\nDie Tentakelhaltung ändert sich zu „Benthos: Tentakelhaltung„.\n\n„Benthos: Ruhiges Meer„: Sofort einen Schild in Höhe von 25% der Max LP erzeugen, und Tentakel greifen am Zugende nicht mehr an; 3 Züge Abklingzeit.\n„Benthos: Tobende Wellen„: Tentakelschaden × 125% für den Zug; nach dem Austeilen von Aktivem Schaden greift 1 Tentakel an; am Zugende wird 1 Tentakel verloren; 3 Züge Abklingzeit.\nDie Reichsbeherrschung wird als „Benthos: Tiefseebeherrschung„ gezählt. Jeder Punkt gewährt: Schildgenerierung der Ruhiges-Meer-Haltung +0,025% Max LP. Tentakelschaden der Tobende-Wellen-Haltung +0,025%.\nDer „Benthos: Reichsbeherrschung„-Effekt verdoppelt sich, wenn das Team ausschließlich aus Aequor- und Chaos-Reich-Erweckern besteht."
  },
