  AwakerTalent_145381_TalentDesc_1 = {
    Text = "·Dieses Talent wirkt nur in „Sternekapitel\"-Levels.\n·KON, Angriff und VERT dieses Erweckers werden um [Arg1] % erhöht, und nachdem dieser Erwecker zum ersten Mal Erwecken spielt, erhält er [Arg2] Keyflare.\n·„Grenzenspaltende Klinge\" genießt einen zusätzlichen STR-Bonus von [Arg3] %. Nach dem Töten eines Feindes werden [Arg4] Schwarze Imprägnierungen erhalten, die den Siegelertrag-Bonus von Lotan: Cetarchon genießen. Wirkt maximal einmal pro Kampf."
  },
  AwakerTalent_145381_TalentDesc_10 = {
    Text = "·Dieses Talent wirkt nur in „Sternekapitel\"-Levels.\n·KON, Angriff und VERT dieses Erweckers werden um [Arg1] % erhöht, und nachdem dieser Erwecker zum ersten Mal Erwecken spielt, erhält er [Arg2] Keyflare.\n·„Grenzenspaltende Klinge\" genießt einen zusätzlichen STR-Bonus von [Arg3] %. Nach dem Töten eines Feindes werden [Arg4] Schwarze Imprägnierungen erhalten, die den Siegelertrag-Bonus von Lotan: Cetarchon genießen. Wirkt maximal einmal pro Kampf."
