  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Wenn Caraboo im Team ist, mutiert das Fleisch-Reich zu Zuchtfleisch.\n\nEmbryofusion: Die pro Runde erhaltene Embryofusion steigt auf 50–100, skalierend mit verlorenen LP. Die Embryofusions-Obergrenze steigt von 100 auf 200. Beim Erreichen der Obergrenze wird 1 „Propagul-Embryo\" auf die Hand gelegt.\n\nPropagul-Embryo: Das Spielen dieser Karte gewährt keine Krit. Rate mehr. Verschlingen gewährt keinen Schild oder Temporäre STR mehr. Wenn jeder Erwecker zum ersten Mal pro Runde einen „Propagul-Embryo\" verbraucht, erhält er 40 Stapelungen „Ausbreitungsfiesta\": Jede Stapelung verstärkt die folgenden Endeffekte der nächsten Verherrlichung dieses Erweckers in dieser Runde um 1 %: Gesamtschaden, Fester Schild, Feste LP-Wiederherstellung, Feste STR/STR▼, Tentakel-Schaden-Bonus, Festes Gift und Fester Konter.\n\nBlutroter Ofen: Die automatische Ansammlung zu Rundenbeginn ändert sich auf 10 % der verlorenen LP, bis zu 50 % der Max LP. Wird am Ende des Kampfes nicht mehr angesammelt. 3 Runden Abklingzeit.\n\nScharlachrote Erosion: Nach dem Einsatz des Blutroten Ofens wird allen Feinden Verfall in Höhe von 1 % ihrer Max LP zugefügt. Je mehr Blutroter Ofen verbraucht wurde, desto stärker der Verfall-Effekt, bis zu +100 %. Gegen „Leere Hülle\"-Feinde wird der 5-fache Verfall-Effekt angewendet.\n\nZu Beginn der Erkundung: Max LP +10 %, Team-Schadenamplifikation +50 %, und alle Erwecker erhalten zu Rundenbeginn 20 Stapelungen „Ausbreitungsfiesta\". Besteht das Team ausschließlich aus Fleisch- oder Chaos-Erweckern, wird die durch diesen Effekt gewährte Schadenamplifikation verdoppelt.\nDie Reichsbeherrschung wird zur „Zuchtfleisch-Beherrschung\": Jeder Punkt Reichsbeherrschung erhöht die durch „Zuchtfleisch\" erhaltenen „Ausbreitungsfiesta\"-Stapelungen um 0,05 %.\n\nBesteht das Team ausschließlich aus Fleisch- oder Chaos-Erweckern, wird der „Zuchtfleisch-Beherrschungs\"-Effekt verdoppelt."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Zuchtfleisch"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Wenn Lotan: Cetarchon im Team ist, wird das Chaos-Reich zu Primordia: Chaos umgeschmiedet.\n\nUrzeitlicher Zufluss: Der Basis-Keyflare wird auf 2000 erhöht, die Schadenamplifikation des Teams wird um 50 % erhöht, und ANG und VERT aller Erwecker werden um 10 % erhöht. Wenn das Team ausschließlich aus Chaoswachkörpern besteht, wird der Schadenamplifikationsbonus dieses Effekts verdoppelt. Zu Beginn des Kampfes werden 2000 Keyflare gewonnen.\n\nVereinte Schlüssel: Die Silberner Schlüssel Aufladelevel aller Erwecker werden auf den Teamdurchschnitt gesetzt. Erwecker erhalten keinen Keyflare mehr durch verbrauchte Arithmetica; stattdessen gewährt die erste Befehlskarte, die jeder Erwecker pro Runde spielt, Keyflare in Höhe von (ihrer Keyflare-Regeneration × 3) + 100.\n\nUnteilbares Reich: Löst nicht mehr die Effekte „Reines Reich“, „Doppelte Reichsbeherrschung“ oder „Doppelte Schadenamplifikation“ anderer Reiche aus.\n\nUrecho: Erwecken-Karten erhalten Vorbereiten 1; die aktuell ausgerüstete Posse wird automatisch entfesselt, wenn sie zum ersten Mal pro Runde gespielt wird.\n\nErinnerungsfragmente: Die Posse wird durch Primordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung ersetzt, und die mitgeführte Posse selbst kann nicht mehr entfesselt werden.\n\n-Primordia: Doppelte Wiederkehr: Entdecke 3 Possen aus denen auf der Hand, dann wähle 1 aus, um sie zweimal zu entfesseln.\n-Primordia: Triade der Offenbarung: Entdecke 3 Possen-Sets aus denen auf der Hand, wobei jedes Set 3 verschiedene Possen enthält. Wähle ein Set aus, um jede darin enthaltene Posse einmal der Reihe nach zu entfesseln.\nDie in Primordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung vorgestellten Possen werden aus den acht Arten der Urerinnerung gezogen.\nPrimordia: Doppelte Wiederkehr und Primordia: Triade der Offenbarung zählen jeweils nur als Entfesselung von 1 Posse. Wenn ihre Effekte mehrfach ausgelöst werden würden, ist nur die erste wirksame Posse gültig.\n\nPrimordia: Chaotische Beherrschung: Die Reichsbeherrschung wird zu Primordia: Chaotische Beherrschung. Jeder Punkt Primordia: Chaotische Beherrschung erhöht die Possen-Potenz um 0,05 %. Jeder Punkt Possen-Potenz erhöht Festes Gift, Festen Gegenangriff, Feste Stärke, Alte Glut um 2 % sowie Festen Schild, Feste LP-Wiederherstellung, Feste STR▼ & Tentakelschaden-Gewinn, Krit. Rate, Krit. Schaden, Schadenamplifikation, Reichsbeherrschung, Aliemus-Generierung, Embryofusion und Keyflare-Generierung um 1 %."
  },
  AwakerTalent_146937_TalentName_1 = {Text = "Urhauch"},
  AwakerTalent_147414_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in Kapitel „Sterne„ wirksam.\n·Die Konstitution, der Angriff und die Verteidigung dieses Erwachten erhöhen sich um [Arg1] %, und nach dem ersten Ausspielen der Karte „Erleuchtung des Wissens„ erhält dieser Erwachte zusätzlich [Arg2] Punkte an S-Energie."
