  AwakerTalent_44845_TalentDesc_1 = {
    Text = "·Wenn Lily selbst, ihr Schicksrad oder ihr Bündnis 1% Todwiderstand bieten, erhöht sich der Grundschild von “Verbotener Sumpf“ und “Grundverteidigung“ um 0,25%, und die Anhäufung sowie das Limit der Ausdauer im Anführer Kampf steigen um 0,25%.\n·Wenn Lily im Team ist, erhält sie beim Verlust von 1 Punkt Leben 1 Schicht Ausdauer, die maximale Stapelgrenze der Ausdauer entspricht der maximalen Gesundheit."
  },
