  AwakerTalent_46445_TalentDesc_1 = {
    Text = "·Der Purpurne Ofen-Heileffekt, den Salvador bereitstellt, wird durch Erhöhungen der Lebensregeneration verstärkt."
  },
  AwakerTalent_46445_TalentName_1 = {
    Text = "Seelenhüter"
  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "·Ramona erhält zusätzlich 2,5 Punkte Keyflare-Regeneration. Für jedes Synchronisationslevel erhält Ramona zusätzlich 0,5 Punkte Keyflare-Regeneration. \n·Für jeden Punkt im Silberner Schlüssel Aufladelevel erhöht sich der Grundschaden von “Schwert der Königin“ um 1 %, nach dem Spielen erhältst du 0,75 temporäre Bereichsbeherrschung."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Herz und Silberresonanz"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "·Ramona: Zeitverwittert erhält zusätzlich 2.5 Punkte Silberner Schlüssel Aufladelevel. Jedes Level der Synchronisationsrate verleiht Ramona zusätzlich 0.5 Punkte Silberner Schlüssel Aufladelevel. \n·Für jeden Punkt Silberner Schlüssel Aufladelevel erhöht der Schleife-Effekt von “Basis-Schlag“ die Krit. Rate von Ramona um 0.2%, der Schleife-Effekt von “Basis-VERT“ gewährt Ramona 0.2 Aliemus."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Herz und Silberresonanz"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "·Für jeden Punkt Reichsbeherrschung, den Nautila besitzt, erhöht sich die Vergeltung von „Bereit und Los“ um 0,25 %."
  },
  AwakerTalent_49872_TalentName_1 = {Text = "Wartung"},
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "·Je 1 % Schaden-Intensität, die Nymphaea besitzt, erhöhen sich die Grundgift-Effekte von „Trauerglocken“ und „mein eigenes Begräbnis“ um 0,5 %."
  },
  AwakerTalent_49873_TalentName_1 = {
    Text = "Verunreinigung"
  },
  AwakerTalent_51744_TalentDesc_1 = {
    Text = "·Zu Beginn des Kampfes erhältst du 1 „Besessenheit \" in die Hand.\n·Miryams „Basisschlag\" erhält 50 % Tentakelschaden-Bonus.\n·Für jeden 1 % Krit. Schaden, den Miryam und ihr ausgerüstetes Schicksrad & Bündnis gewähren, erhöhen sich die STR-Erzeugung, der Tentakelschaden, der Aliemus und die Gift-Anwendung/Auslösung der Verherrlichung um 0, 2 %."
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Unsterbliche Frömmigkeit"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "·Tulu selbst, das ausgestattete Schicksrad und Bündnis bieten für jedes 1 Punkt Wutregenerations-Level einen Bonus von 5% auf Tentakelschaden und Stärke für “Grundschlag“ sowie 15% auf Tentakelschaden und Stärke für “Abgrundsbefehl“."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Göttliche Herrschaftsfähigkeit"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "·Sanga selbst, sein Schicksrad und Bündnis bieten für jeden 1% Todwiderstand, den “Grundschlag“ und “Grundlegende VERT“ erhalten, 0,03 Punkte mehr Wahnsinn. “Die verlorene Kunst“ erhält zusätzlich 0,15% kritische Rate und kritischen Schadenbonus."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Todeserkenntnis"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "·Für jeden Punkt der Wahnsinnsaufladungsstufe, den Puppe besitzt, erhöhen sich die Lebensregenerationswirkungen von „Fernchirurgie“ und „Äquivalenter Austausch“ um 0,5 %."
  },
  AwakerTalent_54047_TalentName_1 = {
    Text = "Gnosis-Dekonstruktion"
  },
  AwakerTalent_54072_TalentDesc_1 = {
    Text = "·Für jeden 1% an schwarzen Siegel, den Ogier besitzt, erhöht sich die temporäre Macht, die durch “sieben Künste und Tugenden“ gewährt wird, um 3%."
  },
  AwakerTalent_54072_TalentName_1 = {
    Text = "Formlose Verfeinerung"
  },
  AwakerTalent_54073_TalentDesc_1 = {
    Text = "·Für jeden 1% Todeswiderstandsmerkmale, die Alva besitzt, erhöht sich der Grundschaden um 0,5%."
  },
  AwakerTalent_54073_TalentName_1 = {
    Text = "Dynamisches Sichtfeld"
  },
