  },
  AwakerTalent_54158_TalentDesc_1 = {
    Text = "·Wenn Sorel selbst, sein Rad des Schicksals oder sein Bündnis 1% kritische Rate besitzen, erhöht sich der Wahnsinn, der durch „Grundlegende VERT“ erhalten wird, um 0,2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Prachtwächter"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "·Jenkins selbst, das Rad des Schicksals und das Bündnis erhöhen den Grundschaden von „Grundschlag“ und „braun, ANG!“ um 2%, wenn sie 1% kritische Rate bereitstellen."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Gemeinsamer Hass"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "·Für jeden Punkt des Silberschlüsselaufladungslevels, den Erica selbst, das Rad des Schicksals oder das Bündnis bereitstellen, erhält Erica durch “elektromagnetische Explosion“ 0,5% temporäre kritische Rate und kritischen Schaden."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Außenanschluss Energie"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = "·Zu Beginn der Runde 1 Schicht Traumköder erhalten. \n·Für jede verbrauchte Schicht Traumköder erhöht sich die ANGskraft des Gegenangriffs von “Hüter der Verlorenen“ und “Nekropolis der Träume“ um 5%. \n·Für jeden 1% Schadenamplifikation, den Wanda's Erwecker, Schicksrad und Bündnis bereitstellen, erhöht sich der Gegenangriff von “Nekropolis der Träume“ um 0,75%."
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Erleuchtung"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "·Für jeden Punkt Reichsbeherrschung, den der Erwecker Casiah selbst sowie das Rad des Schicksals oder das Bündnis bereitstellen, erhöht „Magisches Karneval“ den Grundschaden von Casiah um 0,2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Zaubermeister"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "·Für jeden 1%-Punkt der schwarzen Siegel-Quote, den Tinktur selbst, das Rad des Schicksals oder das Bündnis bereitstellen, erhält „Farbenrausch“ zusätzlich 0,15% temporäre kritische Trefferchance."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Planetenreisender"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "·Horlas “Grundschlag“ und “Grundlegende VERT“ gelten ebenfalls als eine Art Poesie. Bei einem Gedichtsprung wechselt die Stimmung zu einer anderen, die Stimmung kann den Effekt dieser Poesie direkt beeinflussen. Unterschiedliche Stimmungen bringen unterschiedliche anhaltende Effekte für das Team. \n·Für jeden 1 % Todwiderstand, den Horla hat, erhöht sich der Effektzuwachs um 0,1 % des Ausgangswerts."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Stiftzug erzeugt Gefühle"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "·Je 1 % Schadensbonus, den Faros besitzt, erhöht sich der von “Die verlorene uralte Stadt“ erzeugte Schild um 0,4 %."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Heimkehr-Faszination"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "·Für jeden 1%-Punkt des schwarzen Siegels von Caecus erhält “Grundschlag“ einen 1%-Theke-Bonus."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Rebellischer Dorn"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "·Celeste aktiviert eine Kommando-Karte, um 1 Tentakel zu aktivieren, der Gegner angreift; für jeden 1 Punkt der Bereichsmeisterschaft von Celeste, dem Rad und dem Bund, verursacht diese Aktivierung zusätzlich 0.5% Tentakel-Schaden."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Fernfahrerhorn"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "·Für jeden 1 % schwarzen Siegel-Drop-Bonus, den Salvador besitzt, erhöht sich das Limit des Purpurnen Ofens um 0,15 % des maximalen Lebens."
  },
  AwakerTalent_57336_TalentName_1 = {Text = "Anfangsort"},
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "·Für jeden 1 % Siegelertrag, den Agrippa und ihr ausgerüstetes Schicksrad & Bündnis haben, erhöht sich der Basis-Schild von „Blasser Segen \" um 0, 5 % und das Grundgift um 1 %."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Vertragssiegel"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "·Für jeden 1% Todwiderstand, den Faint besitzt, erhöht sich der Gegenangriff von „Wiege der Sterne \" und „Grenzenloses Sternenlicht\" um 0, 2%, und die Todwiderstand-Obergrenze der „Wiege der Sterne \" erhöht sich um 2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Sekundäre Geburtsbinden"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "·Für jeden 1%-Punkt an Schadensverstärkung, den Helot besitzt, erhöht „Notfallüberleben“ den von Helot in dieser Runde verursachten Schaden um 0,3%."
  },
  AwakerTalent_57567_TalentName_1 = {Text = "Schmerzmal"},
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "·Ryker erhält 5 Schwarze Male, wenn er einen Feind tötet. Für jeden 1 % Siegelertrag, den Ryker hat, erhöht sich die erhaltene Menge um 1 %, maximal 5 Mal pro Erkundung.\n·Durch den Kampf erhält man 75/150/300 Schwarze Male, Relikt-Obergrenze +1, wähle am Ende des Kampfes ein <C05_zaowu:„Das Erbe des Chaos\"> und füge es der Reliktliste hinzu."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Gewinner nimmt alles"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "·Im Bosskampf erhält man am Beginn jeder Runde sowie nach der Freisetzung der Wahnsinnsexplosion durch „Schmelze·Dorl“ 1 Schicht „Ende“. „Ende“ kann maximal 10 Schichten aufweisen. Wird die 10. Schicht erreicht, wird 1 Karte „Nihil-Ende“ in die Hand gelegt."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Weg der Vernichtung"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in Kapitel „Sterne\" wirksam.\n·Die KON, der ANG und die VERT dieses Erweckers erhöhen sich um [Arg1] %, und beim ersten Erwecken erhält dieser Erweckte Körper zusätzlich [Arg2] Punkte Keyflare.\n·Jeder Tentakelangriff erhöht den Temporären Tentakelschaden von Tulus ANG um [Arg3] %, maximal [Arg4] Mal pro Runde.\n·Wenn sich 1/2/3 weitere „Lemuria\"-Erwecker im Team befinden, erleiden alle Feinde 10 %/25 %/50 % mehr Tentakelschaden."
