  AwakerTalent_74110_TalentDesc_1 = {
    Text = "·Dieses Talent wirkt nur in den Stufen des \"Stella-Kapitels\".\n·Die Vitalität, der Angriff und die Verteidigung des Erweckers erhöhen sich um [Arg1] %, und der Erwecker erhält [Arg2] Punkte S-Energie nach ihrer ersten Gnosis-Erweckung.\n·Nachdem Sie \"Inspiration\" gespielt haben, erhalten Sie temporäre Kraft, die [Arg3]% der Angriffskraft entspricht, und lösen 1 Mal \"Momentum-Melodie\" aus, die bis zu 5 Mal pro Zug aktiviert werden kann."
