  AwakerTalent_74111_TalentDesc_1 = {
    Text = "· Dieses Talent ist nur in \"Astral Reign\"-Levels effektiv.\n· Die Konstitution, der Angriff und die Verteidigung des Erweckers erhöhen sich um [Arg1] %, und dieser Erwecker erhält nach der ersten Erleuchtung [Arg2] Punkte silberne Schlüsselenergie.\n· Zu Beginn des Kampfes, wenn \"Bestie\"-Gegner vorhanden sind, erhöht sich Casiahs Macht in diesem Kampf um [Arg3] %. \"Poof\" aktiviert den Nachbeben-Effekt des Mischen des gezogenen Kartenstapels bei seiner ersten Freisetzung jedes Zuges."
