  AwakerTalent_74123_TalentDesc_1 = {
    Text = "·Dieses Talent aktiviert sich nur in der „Astralreign“-Phase.\n·Die Konstitution, der Angriff und die Verteidigung dieses Erweckers steigen um [Arg1] %, und bei der ersten Aktivierung des Gnosis-Erwachens erhält der Erwecker [Arg2] Punkte Energie des Silbernen Schlüssels.\n·Der Grundschaden, der durch „Schlag“ und „Präzisionsschnitt“ verursacht wird, erhöht sich um [Arg3] % des in dieser Runde erhaltenen Schilds. Alvas Endschaden, der Gegnern des „Caro“-Bereichs zugefügt wird, steigt um [Arg4] %."
