  AwakerTalent_74134_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in Kapitel “Sterne“ wirksam. \n·Die Konstitution, der ANG und die VERT dieses Erwachten erhöhen sich um [Arg1] %, und nach dem ersten Ausspielen der Karte „Erleuchtung des Wissens“ erhält dieser Erwachte zusätzlich [Arg2] Punkte Keyflare. \n·Der Gesamtschaden, den Helot gegen Feinde im „Schneefeld“ verursacht, erhöht sich um [Arg3] %. Wenn Helot in dieser Runde „Embryo“ verbraucht, erhöht sich der kritische Schaden beim nächsten Schaden, den er in dieser Runde verursacht, um [Arg4] %."
  },
