  AwakerTalent_78618_TalentDesc_1 = {
    Text = "·Dieses Talent aktiviert sich nur in der „Astralreign“-Phase.\n·Die Konstitution, der Angriff und die Verteidigung dieses Erweckers steigen um [Arg1] %, und bei der ersten Aktivierung des Gnosis-Erwachens erhält der Erwecker [Arg2] Punkte Energie des Silbernen Schlüssels.\n·Der durch „Agonie-Erlösung“ verursachte Grundschaden erhöht Pollux' Angriffskraft um [Arg3] %.\n·Jede Stapelung von 50 Schichten der „Sünde“-Markierung platziert ein „Heiliges Herz“ auf der Hand.\n·Wenn die „Sünde“-Markierung 100 Schichten erreicht, ziehe eine deiner eigenen „Fähigkeitskarte“ nach dem dritten Verbrauch.\n·Wenn Schaden verursacht wird, verdoppeln sich die Effekte der „Sünde“-Markierung auf Gegner der „Kirche der Lichtträger“."
  },
