  AwakerTalent_78620_TalentDesc_1 = {
    Text = "Dieses Talent ist nur in den „Astrales Reich“-Stufen wirksam.\nKON, ANG und VERT dieses Erweckers +[Arg1]%, und er erhält [Arg2] Keyflare beim ersten Erwecken.\nZu Kampfbeginn erleiden alle Feinde [Arg3]% mehr Tentakelschaden. Dieser Effekt verdoppelt sich gegen „Aequor“-Feinde. Der Aktive Schaden von „Blitzvergeltung“ gegen „Aequor“-Feinde +[Arg4]%."
  },
