  AwakerTalent_78622_TalentDesc_1 = {
    Text = "·Dieses Talent wirkt nur in den „Stella Kapitel“ Stufen.\n·Die Vitalität, den Angriff und die Verteidigung des Erweckers erhöhen sich um [Arg1] %, und der Erwecker erhält [Arg2] Punkte S-Energie nach ihrer ersten Gnosis Erwachung.\n·Der Verstärkungseffekt der \"Lebendigen Flamme\" erhöht sich um [Arg3]%, zu Beginn der Runde und vor der Abwurfphase, lösche alle \"Brennen\" aus der Hand; für jede Schicht erhält Kaitigra 1 Schicht \"Explosive Flamme\"."
  },
