  AwakerTalent_78624_TalentDesc_1 = {
    Text = "· Dieses Talent ist nur in \"Astral Reign\"-Levels effektiv.\n· Die Konstitution, der Angriff und die Verteidigung des Erweckers erhöhen sich um [Arg1] %, und dieser Erwecker erhält nach der ersten Erleuchtung [Arg2] Punkte silberne Schlüsselenergie.\n· Das Spielen von \"Onyx Plume\" fügt \"Arithmetica Harmony\" nicht hinzu, und die durch \"Cleansing Feathers\" verursachte Korrosion erhöht Castors Angriffskraft um [Arg3] %.\n· Die Korrosion, die Castor bei \"Kirche der Lichtträger\" Gegener verursacht, erhöht sich um [Arg4] %."
