    Text = "Dieses Talent ist nur in den „Astral Reign\"-Kapiteln wirksam.\nKON, ANG und VERT dieses Erweckten Körpers +[Arg1] %, und er erhält [Arg2] Keyflare beim ersten Erwecken.\n„Wahrheit, auch eine Illusion\" erhöht zusätzlich den Gesamtschaden der Verherrlichung anderer Erweckter Körper in dieser Runde um [Arg3] %, und nach der Nutzung sinkt Pickmans Basis-Aliemus um 5."
  },
