  AwakerTalent_78645_TalentDesc_1 = {
    Text = "·Dieses Talent aktiviert sich nur in der „Astralreign“-Phase.\n·Die Konstitution, der Angriff und die Verteidigung dieses Erweckers steigen um [Arg1] %, und bei der ersten Aktivierung des Gnosis-Erwachens erhält der Erwecker [Arg2] Punkte Energie des Silbernen Schlüssels.\n·Die Stärke, die alle Erwecker gewinnen, erhöht sich um [Arg3] %.\n·Clementine fügt „insektoiden“ Gegnern bei Schaden einen Blutungseffekt zu, der [Arg4] % Schaden verursacht. Wenn Clementine in jeder Runde zum ersten Mal einen Schild generiert oder Leben wiederherstellt, verlieren die „insektoiden“ Gegner vorübergehend [Arg5] % ihrer Verteidigung."
  },
