  AwakerTalent_78911_TalentDesc_1 = {
    Text = "·Dieses Talent ist nur in den „Astral Reign\"-Kapiteln wirksam.\n·KON, ANG und VERT dieses Erweckten Körpers +[Arg1] %, und er erhält [Arg2] Keyflare beim ersten Erwecken.\n·Immer wenn Murphy: Wahngeboren Schaden verursacht, werden dem Ziel „Opfergabe\"-Stapelungen in Höhe von [Arg3] % des verursachten Schadens zugefügt. Der Stapelungserhöhungseffekt des „Schicksalsvertrag\"-Zustands für „Geburtsritual\" wird verdoppelt.\n·Wenn sich 1/2/3 andere „Lemuria\"-Erweckte Körper im Team befinden: Max LP +6 %/15 %/30 %; erhalte Rollen-Schild in Höhe von 50 %/125 %/250 % der VERT von Murphy: Wahngeboren, nachdem ein „Lemuria\"-Erweckter Körper Verherrlichung einsetzt. Limitiert auf einmal pro Runde; profitiert nicht von Schilderzeugungsbonus."
