  AwakerTalent_79211_TalentDesc_1 = {
    Text = "·Clementines Befehlskarten verursachen nach Schaden 1 Schicht “Symbiose“.\n·Clementine Erwecker selbst, Schicksrad und Bündnis erhöhen für jede bereitgestellte 1 Punkt s-Energie den Krit. Rate und den Krit. Schaden um 0,35 %.\n·Nach Beginn der Ultra-Runde werden alle “Seelische Verletzungen“ und “Phobische Fixierungen“ der Feinde entfernt. Für jede entfernte Schicht “Seelische Verletzung“ von allen Feinden erhält man 50 Punkte Keyflare, und für jede entfernte Schicht “Phobische Fixierung“ von allen Feinden erhalten andere Erwecker 2 Punkte Aliemus."
  },
  AwakerTalent_79211_TalentName_1 = {Text = "Hive-Sinne"},
