    Text = "·Jedes Mal, wenn „Schwarze Feder„ zum ersten Mal in dieser Runde ausgespielt wird, wird auf das Ziel eine „Korrosion„ in Höhe von 840 % von Castors ANG angewendet und man erhält 10 Aliemus.\n·Für jeden 1 % Schadenamplifikation, die Castor hat, erhöht sich die angewendete Grundkorrosion um 1 %.\n·Nach dem Kampf wird die von Castor in dieser Erkundung angewendete Korrosion dauerhaft um 20 % erhöht.\n·Die Korrosion, die im Anführer Kampf angewendet wird, wird verdoppelt.\n·Nach der Anwendung von Korrosion erhöht sich der eigene Schaden von Castor in dieser Runde um 5 % des Anwendungsbetrags.\n·Der von Castor verursachte Schaden entfernt die Korrosion nicht."
  },
  AwakerTalent_89775_TalentName_1 = {
