  AwakerTalent_98451_TalentDesc_1 = {
    Text = "· Zu Beginn der Runde erhält zufällig eine der Befehlskarten von Kitty Galra im Besitz 1 Stufe „Lebendige Flamme“. \n· Jedes Mal, wenn Kitty Galra 1 Stufe „Lebendige Flamme“ verbraucht, erhält sie 1 Stufe „Explosive Flamme“. \n· Wenn „Explosive Flamme“ 10 Stufen erreicht, erhältst du 2 Rechenpunkte, und alle „Gigantischen Flammen“ werden zu „Trillionen Flammen“ aufgewertet."
  },
